// Renderer half of scripts/inpaint-debug.mjs (bundled as the global `IP`). Runs
// the real drawTranslation, and shows the real plan behind it (planJobs): the
// page's bubbles and the parts each block owns. `./.gen/inpaint` = src/renderer/
// src/inpaint.ts with its internals exported (generated by the script).
import type { TransResult } from '../../src/shared/ipc'
import { drawTranslation, loadImage, canvasSize, isSfx, planJobs, layoutAll, targetFont, healPage, autoPage, renderDoc } from './.gen/inpaint'

const COLOURS = [
  [0, 160, 255],
  [255, 160, 0],
  [0, 200, 90],
  [200, 0, 220],
  [255, 230, 0],
  [0, 220, 220]
]

export async function debugRun(src: string, res: TransResult): Promise<{ result: string; debug: string; info: unknown }> {
  if (res.mask) res.mask.bits = Uint8Array.from(res.mask.bits as unknown as number[])
  const img = await loadImage(src)
  const out = document.createElement('canvas')
  const t0 = performance.now()
  // Under IP_LAMA the window has node: the app's preload calls, straight to ipc.
  const req = (window as unknown as { require?: (m: string) => typeof import('electron') }).require
  if (req) {
    const { ipcRenderer } = req('electron')
    ;(window as unknown as { api: object }).api = {
      lamaStatus: () => ipcRenderer.invoke('lama:status'),
      lamaPatch: (rgb: Uint8Array, mask: Uint8Array) => ipcRenderer.invoke('lama:patch', rgb, mask)
    }
  }
  const heal = req ? await healPage(img, res) : null
  const drawn = drawTranslation(out, img, res, { heal })
  const ms = Math.round(performance.now() - t0)
  // The editor's layers for the same page (autoPage → renderDoc): must match.
  const idRes = { ...res, blocks: res.blocks.map((b, i) => ({ ...b, id: `b${i}` })) }
  const auto = autoPage(img, idRes, heal)
  const { W: dW, H: dH } = canvasSize(img)
  const er = document.createElement('canvas')
  er.width = dW
  er.height = dH
  er.getContext('2d')!.putImageData(auto.erase, 0, 0)
  const docC = document.createElement('canvas')
  renderDoc(
    docC,
    img,
    {
      v: 1,
      W: dW,
      H: dH,
      blocks: auto.blocks,
      regions: auto.regions.map((r) => ({ ...r, layer: 'auto' })),
      layers: [
        { id: 'text', name: '', kind: 'text', visible: true },
        { id: 'erase', name: '', kind: 'pixels', visible: true }
      ]
    },
    new Map([['erase', er]])
  )
  const pa = out.getContext('2d')!.getImageData(0, 0, dW, dH).data
  const pb = docC.getContext('2d')!.getImageData(0, 0, dW, dH).data
  let docDiff = 0
  for (let i = 0; i < pa.length; i += 4) if (Math.abs(pa[i] - pb[i]) + Math.abs(pa[i + 1] - pb[i + 1]) + Math.abs(pa[i + 2] - pb[i + 2]) > 6) docDiff++

  const { W, H } = canvasSize(img)
  const clean = document.createElement('canvas')
  clean.width = W
  clean.height = H
  const cctx = clean.getContext('2d', { willReadFrequently: true })!
  cctx.drawImage(img, 0, 0, W, H)
  const dbg = document.createElement('canvas')
  dbg.width = W
  dbg.height = H
  const dctx = dbg.getContext('2d', { willReadFrequently: true })!
  dctx.drawImage(img, 0, 0, W, H)
  const over = dctx.getImageData(0, 0, W, H)
  const tint = (o: number, [r, g, b]: number[], a: number): void => {
    over.data[o] = over.data[o] * (1 - a) + r * a
    over.data[o + 1] = over.data[o + 1] * (1 - a) + g * a
    over.data[o + 2] = over.data[o + 2] * (1 - a) + b * a
  }

  const { jobs, bubbles } = planJobs(cctx, res, W, H)
  const layouts = layoutAll(cctx, jobs)
  // Bubbles striped, one colour per lobe.
  let k = 0
  const bubbleInfo = bubbles.map((bb) => ({
    rect: [bb.x0, bb.y0, bb.w, bb.h],
    kind: bb.kind,
    fill: bb.fill,
    note: bb.note,
    rays: bb.rays && { centre: [bb.rays.cx, bb.rays.cy], radius: bb.rays.radius.map(Math.round) },
    lobes: bb.lobes.map((s) => {
      const c = COLOURS[k++ % COLOURS.length]
      for (let y = 0; y < s.h; y++)
        for (let x = 0; x < s.w; x++)
          if (s.inside[y * s.w + x] && (s.x0 + x + s.y0 + y) % 8 < 3) tint(((s.y0 + y) * W + s.x0 + x) * 4, c, 0.7)
      return { centre: [Math.round(s.x0 + s.cx), Math.round(s.y0 + s.cy)], area: s.area, ink: s.ink }
    })
  }))
  const blocks = res.blocks.map((b, i) => {
    const row: Record<string, unknown> = { i, box: [b.x, b.y, b.w, b.h].map(Math.round), size: b.size, paras: b.paras, text: b.text, sfx: isSfx(b, W, H) }
    const job = jobs.find((j) => j.i === i)
    if (!job) return row
    row.target = targetFont(b)
    row.ink = job.ink
    row.halo = job.halo
    row.bubble = job.bubble ? job.bubble.kind : null
    row.room = job.parts.some((s) => s.room)
    if (job.into) row.into = job.into.i
    // Per 10th of its height: where the part runs left / right on that row.
    const rowsOf = (s: (typeof job.parts)[number]): number[][] =>
      Array.from({ length: 9 }, (_, k) => {
        const y = Math.round(s.top + ((s.bottom - s.top) * (k + 1)) / 10)
        let l = -1
        let r = -1
        for (let x = 0; x < s.w; x++)
          if (s.inside[y * s.w + x]) {
            if (l < 0) l = x
            r = x
          }
        return [s.y0 + y, s.x0 + l, s.x0 + r, Math.round(s.half[y])]
      })
    row.parts = job.parts.map((s) => ({ centre: [Math.round(s.x0 + s.cx), Math.round(s.y0 + s.cy)], area: s.area, rows: rowsOf(s) }))
    row.layout = (layouts.get(job) ?? []).map((l) => ({ fs: l.fs, lines: l.lines, over: l.over }))
    // Owned parts tinted per block.
    job.parts.forEach((s, p) => {
      for (let y = 0; y < s.h; y++)
        for (let x = 0; x < s.w; x++)
          if (s.inside[y * s.w + x]) tint(((s.y0 + y) * W + s.x0 + x) * 4, COLOURS[(i + p) % COLOURS.length], 0.3)
    })
    return row
  })
  dctx.putImageData(over, 0, 0)
  // A plain bubble's traced outline (where its rays left the fill).
  for (const bb of bubbles) {
    if (!bb.rays) continue
    const { cx, cy, radius } = bb.rays
    dctx.strokeStyle = 'magenta'
    dctx.lineWidth = 1
    dctx.beginPath()
    radius.forEach((r, k) => {
      const a = (2 * Math.PI * k) / radius.length
      dctx.lineTo(cx + Math.cos(a) * r, cy + Math.sin(a) * r)
    })
    dctx.closePath()
    dctx.stroke()
  }
  res.blocks.forEach((b, i) => {
    dctx.strokeStyle = 'red'
    dctx.lineWidth = 2
    dctx.strokeRect(b.x, b.y, b.w, b.h)
    dctx.fillStyle = 'red'
    dctx.font = 'bold 16px sans-serif'
    dctx.fillText(String(i), b.x + 3, b.y + 16)
  })
  // The editor's boxes (where each translation was drawn), dashed purple.
  dctx.setLineDash([8, 5])
  drawn.boxes.forEach((r) => {
    if (!r || r.skip) return
    dctx.strokeStyle = 'rgb(113,50,245)'
    dctx.lineWidth = 3
    dctx.strokeRect(r.x, r.y, r.w, r.h)
  })
  dctx.setLineDash([])
  const boxes = drawn.boxes.map((r, i) => (r ? { i, rect: [r.x, r.y, r.w, r.h].map(Math.round), skip: !!r.skip } : { i, into: drawn.lead[i] }))
  return { result: out.toDataURL('image/png'), debug: dbg.toDataURL('image/png'), doc: docC.toDataURL('image/png'), info: { ms, docDiff, bubbles: bubbleInfo, blocks, boxes } }
}
